void fill(SDL_Surface* target,SDL_Rect box,SDL_Color color){SDL_FillRect(target,&box,SDL_MapRGBA(target->format,color.r,color.g,color.b,color.a));}
void border(SDL_Surface* target,SDL_Rect box,SDL_Color c,int width=1){fill(target,{box.x,box.y,box.w,width},c);fill(target,{box.x,box.y+box.h-width,box.w,width},c);fill(target,{box.x,box.y,width,box.h},c);fill(target,{box.x+box.w-width,box.y,width,box.h},c);}
bool inside(SDL_Rect r,int x,int y){return x>=r.x&&y>=r.y&&x<r.x+r.w&&y<r.y+r.h;}
std::pair<int,int> pixel(int x,int y){const auto& s=state();return {int(std::floor((x-s.image_rect.x)/s.zoom)),int(std::floor((y-s.image_rect.y)/s.zoom))};}
void checkers(SDL_Surface* target,SDL_Rect r,int step=12){SDL_Rect old;SDL_GetClipRect(target,&old);SDL_SetClipRect(target,&r);for(int y=r.y;y<r.y+r.h;y+=step)for(int x=r.x;x<r.x+r.w;x+=step){bool light=((x-r.x)/step+(y-r.y)/step)%2;fill(target,{x,y,step,step},light?SDL_Color{91,96,104,255}:SDL_Color{65,71,79,255});}SDL_SetClipRect(target,&old);}
void thumbnail(SDL_Surface* target,const Resource& resource,SDL_Rect dest){
 static std::map<std::string,V> cache;static uint64_t rev=0;if(rev!=revision()){cache.clear();rev=revision();}V image;
 auto key=resource.key+":"+std::to_string(dest.w)+":"+std::to_string(dest.h);auto it=cache.find(key);
 if(it!=cache.end())image=it->second;else try{V raw=artwork(resource.key);if(raw.is_none())raw=original(resource);auto* src=pg::surf(raw);int w=src->w(),h=src->h();SDL_Rect region{0,0,w,h};if(h>=w*3&&h%w==0)region.h=w;const double z=std::min(double(dest.w)/region.w,double(dest.h)/region.h);int tw=std::max(1,int(region.w*z)),th=std::max(1,int(region.h*z));image=pg::new_surface(tw,th,true);SDL_Rect d{0,0,tw,th};SDL_BlitScaled(src->s,&region,pg::surf(image)->s,&d);if(cache.size()>256)cache.clear();cache[key]=image;}catch(const std::exception&){return;}
 auto* im=pg::surf(image);SDL_Rect box{dest.x+(dest.w-im->w())/2,dest.y+(dest.h-im->h())/2,im->w(),im->h()};SDL_BlitSurface(im->s,nullptr,target,&box);
}
void change(){state().dirty=true;state().local_enabled=true;}
void sethex(){auto& s=state();std::ostringstream o;o<<std::hex<<std::setfill('0')<<std::setw(8)<<s.color;s.hex_input=o.str();}
std::vector<const Resource*> filtered(){auto& s=state();std::vector<const Resource*> out;for(const auto& r:s.resources){
 if(s.filter=="已修改"&&!s.document["entries"].contains(r.key))continue;
 if(s.filter=="弹幕"&&!r.projectile)continue;
 if(s.filter=="场景"&&r.category!="场景")continue;
 if(s.filter=="界面"&&r.scope!="ui")continue;
 if(!s.card_filter.empty()&&std::find(r.cards.begin(),r.cards.end(),s.card_filter)==r.cards.end())continue;
 if(!s.hero_filter.empty()&&std::find(r.heroes.begin(),r.heroes.end(),s.hero_filter)==r.heroes.end())continue;
 if(!s.query.empty()&&r.name.find(s.query)==std::string::npos&&r.key.find(s.query)==std::string::npos)continue;out.push_back(&r);}return out;}
void select_all(){auto& s=state();s.selection={0,0,s.canvas.w,s.canvas.h};}
void copy_selection(bool cut){auto& s=state();if(s.selection.w<=0)select_all();auto r=s.selection;s.clip_w=r.w;s.clip_h=r.h;s.clipboard.resize(size_t(r.w)*r.h);auto& p=s.canvas.layers.at(s.canvas.selected).pixels;if(cut)s.canvas.checkpoint();for(int y=0;y<r.h;++y)for(int x=0;x<r.w;++x){auto at=size_t(y+r.y)*s.canvas.w+x+r.x;s.clipboard[size_t(y)*r.w+x]=p[at];if(cut)p[at]=0;}if(cut)change();set_notice(cut?"选区已剪切":"选区已复制");}
void paste(){auto& s=state();if(s.clipboard.empty())return;s.canvas.checkpoint();auto& p=s.canvas.layers.at(s.canvas.selected).pixels;int ox=s.selection.w?s.selection.x:(s.canvas.w-s.clip_w)/2,oy=s.selection.h?s.selection.y:(s.canvas.h-s.clip_h)/2;for(int y=0;y<s.clip_h;++y)for(int x=0;x<s.clip_w;++x){int xx=x+ox,yy=y+oy;if(xx>=0&&yy>=0&&xx<s.canvas.w&&yy<s.canvas.h)p[size_t(yy)*s.canvas.w+xx]=s.clipboard[size_t(y)*s.clip_w+x];}change();}
void erase_selection(){auto& s=state();if(!s.selection.w)select_all();s.canvas.checkpoint();for(int y=s.selection.y;y<s.selection.y+s.selection.h;++y)for(int x=s.selection.x;x<s.selection.x+s.selection.w;++x)s.canvas.layers.at(s.canvas.selected).pixels[size_t(y)*s.canvas.w+x]=0;change();}
void transform_layer(const std::string& op){auto& s=state();auto& c=s.canvas;c.checkpoint();auto before=c.layers.at(c.selected).pixels;auto& p=c.layers.at(c.selected).pixels;
 for(int y=0;y<c.h;++y)for(int x=0;x<c.w;++x){int xx=x,yy=y;if(op=="flip_h")xx=c.w-1-x;else if(op=="flip_v")yy=c.h-1-y;else{xx=y+(c.w-c.h)/2;yy=c.h-1-x+(c.w-c.h)/2;}p[size_t(y)*c.w+x]=xx>=0&&yy>=0&&xx<c.w&&yy<c.h?before[size_t(yy)*c.w+xx]:0;}change();}
void zoom_at(int x,int y,double factor){auto& s=state();auto old=s.zoom;auto next=std::clamp(old*factor,.05,64.);s.panx=(s.panx+x-s.viewport.x-s.viewport.w*.5)*(next/old)-(x-s.viewport.x-s.viewport.w*.5);s.pany=(s.pany+y-s.viewport.y-s.viewport.h*.5)*(next/old)-(y-s.viewport.y-s.viewport.h*.5);s.zoom=next;}
void apply_slider(int x){auto& s=state();int channel=s.active_slider;if(channel<0||channel>=4||s.sliders.size()<4)return;auto r=s.sliders[channel];int value=std::clamp(255*(x-r.x)/std::max(1,r.w),0,255);int shift=24-channel*8;s.color=(s.color&~(0xffu<<shift))|(uint32_t(value)<<shift);sethex();}
void canvas_down(int x,int y,int button){auto& s=state();if(!inside(s.viewport,x,y))return;if(s.tool=="hand"||s.space_down||button==2){s.panning=true;s.pan_mouse_x=x;s.pan_mouse_y=y;return;}
 auto [px,py]=pixel(x,y);if(px<0||py<0||px>=s.canvas.w||py>=s.canvas.h)return;s.sx=s.lastx=px;s.sy=s.lasty=py;
 if(s.tool=="picker"||(SDL_GetModState()&KMOD_ALT)){s.color=s.canvas.flatten()[size_t(py)*s.canvas.w+px];sethex();return;}
 if(s.tool=="select"){s.dragging=true;s.selection={px,py,1,1};return;}
 if(s.tool=="move"){if(!s.selection.w)select_all();copy_selection(false);s.canvas.checkpoint();auto& p=s.canvas.layers.at(s.canvas.selected).pixels;for(int yy=s.selection.y;yy<s.selection.y+s.selection.h;++yy)for(int xx=s.selection.x;xx<s.selection.x+s.selection.w;++xx)p[size_t(yy)*s.canvas.w+xx]=0;s.preview=p;s.dragging=true;return;}
 s.canvas.checkpoint();s.dragging=true;s.erasing=s.tool=="eraser"||button==3;s.preview=s.canvas.layers.at(s.canvas.selected).pixels;
 if(s.tool=="fill"){s.canvas.fill(px,py,s.color);s.dragging=false;change();}else if(s.tool=="pencil"||s.erasing){s.canvas.dot(px,py,s.brush,s.color,s.erasing);change();}
}
void canvas_motion(int x,int y){auto& s=state();if(s.active_slider>=0){apply_slider(x);return;}if(s.panning){s.panx+=x-s.pan_mouse_x;s.pany+=y-s.pan_mouse_y;s.pan_mouse_x=x;s.pan_mouse_y=y;return;}if(!s.dragging)return;auto [px,py]=pixel(x,y);px=std::clamp(px,0,s.canvas.w-1);py=std::clamp(py,0,s.canvas.h-1);
 if(s.tool=="select"){s.selection={std::min(px,s.sx),std::min(py,s.sy),std::abs(px-s.sx)+1,std::abs(py-s.sy)+1};return;}
 if(s.tool=="move"){auto& p=s.canvas.layers.at(s.canvas.selected).pixels;p=s.preview;int ox=s.selection.x+px-s.sx,oy=s.selection.y+py-s.sy;for(int yy=0;yy<s.clip_h;++yy)for(int xx=0;xx<s.clip_w;++xx){int dx=ox+xx,dy=oy+yy;if(dx>=0&&dy>=0&&dx<s.canvas.w&&dy<s.canvas.h)p[size_t(dy)*s.canvas.w+dx]=s.clipboard[size_t(yy)*s.clip_w+xx];}s.lastx=px;s.lasty=py;change();return;}
 if(s.tool=="pencil"||s.erasing)s.canvas.line(s.lastx,s.lasty,px,py,s.brush,s.color,s.erasing);
 else {s.canvas.layers.at(s.canvas.selected).pixels=s.preview;if(s.tool=="line")s.canvas.line(s.sx,s.sy,px,py,s.brush,s.color);else s.canvas.shape(s.sx,s.sy,px,py,s.brush,s.color,s.tool=="ellipse",s.solid);}s.lastx=px;s.lasty=py;change();
}
void end_stroke(){auto& s=state();if(s.tool=="move"&&s.dragging){s.selection.x=std::clamp(s.selection.x+s.lastx-s.sx,0,s.canvas.w-s.selection.w);s.selection.y=std::clamp(s.selection.y+s.lasty-s.sy,0,s.canvas.h-s.selection.h);}s.dragging=false;s.panning=false;s.active_slider=-1;s.preview.clear();}
